def config():
    g.load_env()

    return {
        "discogs_url" : g.DISCOGS_URL(),
        "discogs_key" : g.DISCOGS_USER_TOKEN(),
        "lastfm_url" : g.LASTFM_URL(),
        "lastfm_key" : g.LASTFM_KEY(),
        "musicbrainz_url" : g.MUSIC_BRAINZ_URL()
    }
def test_auth_user(mocker):
    mock_get = mocker.patch("cd_ripper.fetcher.discogs_client.Client")

    mock_get.return_value = discogs_auth_test

    result = fetcher.auth_user()

    assert result == discogs_auth_test
    mock_get.assert_called_once()

def test_get_album_discogs(mocker):
    mock_get = mocker.patch("cd_ripper.fetcher.requests.get")

    mock_get.return_value.status_code = 200
    mock_get.return_value.json.return_value = discogs_test

    query = "daydream nation by sonic youth"
    result = fetcher.get_album_discogs(query)

    master_id = discogs_auth_test['master_id']

    assert result == discogs_test
    mock_get.assert_called_once_with(config()["discogs_url"] + str(master_id), timeout=20)

def test_get_album_lastfm(mocker):
    mock_get = mocker.patch("cd_ripper.fetcher.requests.get")

    mock_get.return_value.status_code = 200
    mock_get.return_value.json.return_value = last_fm_test

    artist = "Sonic Youth"
    album = "goo"

    result = fetcher.get_album_lastfm(artist, album, False)

    api_key = f"&api_key={config()['lastfm_key']}"
    artist_str = f"&artist={artist}"
    album_str = f"&album={album}"
    format_str = "&format=json"
    query = config()['lastfm_url'] + api_key + artist_str + album_str + format_str

    assert result == last_fm_test
    mock_get.assert_called_once_with(query, timeout=20)

def test_fetch_date_from_music_brain():
    mbid = "18eb7b48-83a5-49d8-b8a0-04ee2b123b2d"
    soup = BeautifulSoup(xmlRespStr, features="xml")
    result = fetcher.fetch_date_from_music_brainz(mbid, False)
    assert result == util.convert_date_str(soup.find("first-release-date").string)